# frozen_string_literal: true

# Hand-written (not generated by Fern). Restored after every regeneration by
# sdk-extras/restore-manifests.sh, which also requires it from lib/vobiz.rb.
#
# Vobiz authenticates every request with two headers: X-Auth-ID and X-Auth-Token.
# The Fern Ruby generator only surfaces the first header scheme, so the generated
# Vobiz::Client accepts `api_key:` (X-Auth-ID) but has no way to send X-Auth-Token.
# This adds the `auth_token:` keyword and sends it as X-Auth-Token:
#
#   client = Vobiz::Client.new(api_key: "MA_XXXXXXXX", auth_token: "YOUR_AUTH_TOKEN")
#
# If a future generator version accepts `auth_token:` natively, this is a no-op.

module Vobiz
  module AuthTokenHeader
    def initialize(api_key:, auth_token: nil, **kwargs)
      super(api_key: api_key, **kwargs)
      return if auth_token.nil?

      @raw_client.instance_variable_get(:@default_headers)["X-Auth-Token"] = auth_token.to_s
    end
  end

  unless Client.instance_method(:initialize).parameters.any? { |_type, name| name == :auth_token }
    Client.prepend(AuthTokenHeader)
  end
end
